# ===== UNIT 5: PHARMACOECONOMICS & ACCOUNTING (15 new) =====
q.append({"unit_id": "mgmt-unit-5", "question_text": "The law of supply states that, other things being equal:", "options": ["Quantity supplied of a good rises as its price rises", "Quantity supplied rises as the price falls", "Supply is always fixed whatever the price", "Suppliers reduce output when prices increase"], "correct_index": 0, "explanation": "The law of supply describes the direct relationship between price and quantity supplied: higher prices attract more output because profits rise.", "difficulty": "easy", "tags": ["pharmacoeconomics", "supply"]})
q.append({"unit_id": "mgmt-unit-5", "question_text": "Price elasticity of demand measures:", "options": ["How responsive the quantity demanded is to a change in price", "The total profit earned from each product", "The number of substitutes a competitor offers", "How quickly medicines expire on the shelf"], "correct_index": 0, "explanation": "Elasticity of demand is the percentage change in quantity demanded divided by the percentage change in price; it shows demand sensitivity to price.", "difficulty": "medium", "tags": ["pharmacoeconomics", "elasticity"]})
q.append({"unit_id": "mgmt-unit-5", "question_text": "Cost-minimization analysis (CMA) in pharmacoeconomics is used when:", "options": ["Two treatments have equal outcomes, so only their costs are compared", "Treatments differ in both cost and clinical outcome", "No treatment costs need measuring at all", "Only the patient's quality of life is compared"], "correct_index": 0, "explanation": "CMA assumes the alternatives are therapeutically equivalent, so the decision is made purely on which option costs less.", "difficulty": "hard", "tags": ["pharmacoeconomics", "CMA"]})
