q.append({"unit_id": "mgmt-unit-5", "question_text": "A sunk cost is a cost that:", "options": ["Has already been incurred and cannot be recovered by any future decision", "Will be paid only if the project succeeds", "Varies directly with the quantity produced", "Is paid to the government as tax"], "correct_index": 0, "explanation": "Sunk costs (e.g., money already spent on research) are irrelevant to future decisions because they cannot be changed or recovered.", "difficulty": "medium", "tags": ["pharmacoeconomics", "costs"]})
q.append({"unit_id": "mgmt-unit-5", "question_text": "The incremental cost-effectiveness ratio (ICER) is calculated as:", "options": ["(Cost of new treatment - cost of comparator) divided by (effect of new treatment - effect of comparator)", "Total cost of the new treatment multiplied by its total effect", "Effect of the new drug divided by the effect of placebo", "The price of one tablet in the local market"], "correct_index": 0, "explanation": "ICER expresses the extra cost per extra unit of health gain of one treatment over another, guiding value-for-money decisions.", "difficulty": "hard", "tags": ["pharmacoeconomics", "ICER"]})
q.append({"unit_id": "mgmt-unit-5", "question_text": "An income statement (profit and loss account) of a pharmacy reports:", "options": ["Revenues and expenses over a period to show the net profit or loss", "The value of assets and liabilities at one date", "Only the cash received from debtors", "The market share of the pharmacy"], "correct_index": 0, "explanation": "The income statement matches sales revenue against expenses over an accounting period to arrive at net profit or loss.", "difficulty": "medium", "tags": ["accounting", "income statement"]})
q.append({"unit_id": "mgmt-unit-5", "question_text": "The accounting equation is expressed as:", "options": ["Assets = Liabilities + Owner's equity", "Assets = Revenue - Expenses", "Liabilities = Assets + Owner's equity", "Profit = Assets - Liabilities + Equity"], "correct_index": 0, "explanation": "The fundamental accounting equation states that everything the firm owns (assets) is financed by creditors (liabilities) and owners (equity).", "difficulty": "easy", "tags": ["accounting", "accounting equation"]})
q.append({"unit_id": "mgmt-unit-5", "question_text": "The current ratio of a business is used to measure its:", "options": ["Short-term liquidity by comparing current assets with current liabilities", "Long-term profitability over five years", "Total sales compared with last year", "Number of employees per branch"], "correct_index": 0, "explanation": "Current ratio = current assets ÷ current liabilities; it shows whether the firm can meet obligations due within the year.", "difficulty": "medium", "tags": ["accounting", "ratios"]})
