q.append({"unit_id": "mgmt-unit-5", "question_text": "Tax Deducted at Source (TDS) means that:", "options": ["Tax is withheld from a payment (such as salary) and deposited to the government on the payee's behalf", "Tax is collected only at the end of the business year", "The customer pays tax directly to the foreign supplier", "All medicines are exempt from any tax"], "correct_index": 0, "explanation": "Under TDS the payer deducts a percentage from specified payments and remits it to the tax authority, crediting it against the recipient's liability.", "difficulty": "medium", "tags": ["accounting", "taxation"]})
